module ncore_tb;
  reg [7:0] safe_rom [0:255];
  reg [7:0] ram [0:255];
  reg [7:0] cache [0:1];
  reg [7:0] cache_v [0:1];
  reg cache_rdy [0:2];
  reg [31:0] regfile [0:3];
  reg [31:0] key [0:0];
  reg [31:0] tck = 32'd0;
  reg emode;
  wire [3:0] opcode;
  integer pc = 0;
  // assign opcode = ram[pc][3:0];
  reg clk = 0;
