  // memory
  logic [7:0] mem [15:0];
  integer state = `RDY;
  integer cc = 0;
  integer addr = 0;
  integer branch_pred = 0;
  integer wrong_attmpt = 0;
  reg is_ram = 1;

  task increment_pc();
    pc = pc + 2;
  endtask

  task load_safeROM();
    // $display("loading safe rom, safely...");
    $readmemh("flag.hex",safe_rom);
  endtask

  task load_ram();
    // $display("loading user controlled memory...");
    $readmemh("ram.hex",ram);
  endtask

  task open_file();
    // $display("Opening file");
    read_file_descriptor=$fopen("flag.txt","rb");
  endtask

  task set_key();
    int tmp;
    // key[0] = 0;
    // key[0] = $random();
    read_file_descriptor=$fopen("/dev/urandom","rb");
    tmp = $fread(key, read_file_descriptor);
    $readmemh("/dev/urandom",key);
  endtask

  task print_res();
    integer i;
    for( i=0; i<64; i = i + 1) begin
      $write("%h ",ram[255-i]);
    end
    $write("\n");
  endtask

  task init_regs();
    integer i = 0;
    for(i = 0; i<4; i++) begin
      regfile[i] = 32'd0;
    end
  endtask

  always begin
    #5 begin
      clk <= ~clk;
      tck <= tck + 1;
    end
  end

