        // ADDR NT : regfile[ram[pc+2][7:6]] + safe_rom[pc+3] 
        if (branch_pred>=0) begin
          if (ram[ram[pc+1]][3:0] == `MOVFI) begin
            cache[cc] <= ram[ram[ram[pc+1]+1]] + regfile[ram[ram[pc+1]][7:6]];
