  // $display("PC:%h | OPCODE: %d ADDR: %d",pc,ram[pc][3:0],ram[pc+1]);
  case(state)
  `LOCKED: begin

  end
  `DSTAGE_1: begin
    tmp <= ram[addr];
    state <= `DSTAGE_2;
  end
  `DSTAGE_2: begin
    regfile[ram[pc][5:4]] <= tmp;
    state <= `RDY;
    increment_pc();
  end 
  `MSTAGE_1: begin
    if (is_ram) begin
      cache_rdy[cc] <= 1;
      cache[cc] <= addr;
      cache_v[cc] <= ram[addr];
      cc <= (cc + 1)%2;
    end else begin
      cache_rdy[cc] <= 2;
      cache[cc] <= addr;
      cache_v[cc] <= safe_rom[addr];
      cc <= (cc + 1)%2;
  end
  state <= `MSTAGE_2;
  end
  `MSTAGE_2: begin
    regfile[ram[pc][5:4]] <= cache_v[(cc + 1)%2];
